// Package: ModelContextProtocol
// Package: Microsoft.Extensions.DependencyInjection
using ModelContextProtocol.Server;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddMcpServer()
    .WithTools<WeatherTools>()
    .WithResources<CustomerResources>()
    .WithPrompts<SupportPrompts>()
    .WithStdioTransport();

var app = builder.Build();
await app.RunAsync();
// Expected output when started:
//   Registered tools: search_products, get_customer
//   Registered resources: customer://{id}, catalog://products
//   Registered prompts: support_triage
//   Transport: stdio
